// Vorlesen in the Android app: Android's WebView has no Web Speech API (window.speechSynthesis is missing), so the
// read-aloud in the viewer, the Word editor, the Formular-Lotse and the KI answers would silently not exist there.
// This module offers the small part of speechSynthesis FaLe uses (speak/cancel/getVoices, utterance events) on top
// of the system text-to-speech (FaleSpeech plugin, generated by scripts/cap-patch-android.mjs).
// Imported by app.js before anything that checks for speech support (js/readaloud.js reads it once at load).
import { isNative, platformName, plugin } from './platform.js';

let warned = false;
function warnMissing() {
  if (warned) return;
  warned = true;
  import('./ui.js').then(m => m.toast('Auf diesem Gerät ist keine Sprachausgabe eingerichtet. Du findest sie in den Android-Einstellungen unter „Sprachausgabe“.', 'info', { timeout: 7000 })).catch(() => {});
}

export function installSpeechShim(w = window) {
  try {
    if ('speechSynthesis' in w && w.speechSynthesis) return false; // the real thing (browsers, iPhone app)
    if (!isNative() || platformName() !== 'android') return false;
    const P = plugin('FaleSpeech');
    if (!P) return false;
    const live = new Map(); // id → utterance
    let n = 0;
    const fire = (u, type, extra = {}) => {
      const ev = { type, utterance: u, charIndex: 0, elapsedTime: 0, ...extra };
      try { const f = u['on' + type]; if (typeof f === 'function') f.call(u, ev); } catch (e) { console.warn(e); }
      for (const f of (u._ls[type] || []).slice()) { try { f.call(u, ev); } catch (e) { console.warn(e); } }
    };
    const synth = {
      speaking: false, pending: false, paused: false, onvoiceschanged: null,
      getVoices: () => VOICES,
      speak(u) {
        if (!u || typeof u.text !== 'string') return;
        const id = 'u' + (++n);
        live.set(id, u);
        synth.speaking = true;
        const lang = (u.voice && u.voice.lang) || u.lang || (navigator.language || 'de-DE');
        Promise.resolve(P.speak({ text: u.text, lang, rate: Number(u.rate) || 1, id })).catch(() => {
          if (!live.delete(id)) return;
          if (!live.size) synth.speaking = false;
          warnMissing();
          fire(u, 'error', { error: 'synthesis-unavailable' });
        });
      },
      cancel() {
        const all = [...live.values()];
        live.clear();
        synth.speaking = false;
        Promise.resolve(P.stop()).catch(() => {});
        all.forEach(u => fire(u, 'error', { error: 'canceled' }));
      },
      pause() { synth.cancel(); }, // the system engine cannot pause; FaLe's player resumes from the current sentence
      resume() {},
      addEventListener() {}, removeEventListener() {},
    };
    Promise.resolve(P.addListener('speech', d => {
      const u = d && live.get(d.id);
      if (!u) return;
      if (d.type === 'start') { fire(u, 'start'); return; }
      live.delete(d.id);
      if (!live.size) synth.speaking = false;
      if (d.type === 'end') fire(u, 'end');
      else fire(u, 'error', { error: d.type === 'cancel' ? 'interrupted' : 'synthesis-failed' });
    })).catch(() => {});
    class Utterance {
      constructor(text = '') { this.text = String(text); this.lang = ''; this.rate = 1; this.pitch = 1; this.volume = 1; this.voice = null; this._ls = {}; }
      addEventListener(type, f) { (this._ls[type] = this._ls[type] || []).push(f); }
      removeEventListener(type, f) { this._ls[type] = (this._ls[type] || []).filter(x => x !== f); }
    }
    const dev = (navigator.language || 'de-DE').replace('_', '-');
    const VOICES = [{ voiceURI: 'fale-android-de', name: 'Deutsch (Sprachausgabe des Geräts)', lang: 'de-DE', localService: true, default: /^de/i.test(dev) }];
    if (!/^de/i.test(dev)) VOICES.unshift({ voiceURI: 'fale-android-device', name: `${dev} (Sprachausgabe des Geräts)`, lang: dev, localService: true, default: true });
    w.SpeechSynthesisUtterance = Utterance;
    w.speechSynthesis = synth;
    w.__faleSpeechShim = true;
    return true;
  } catch (e) {
    console.warn('Vorlesen: Sprachausgabe nicht verfügbar', e);
    return false;
  }
}

installSpeechShim();
